-- Item-only Alumdoor import generated from catalog-new.tsv.

-- Compared with items-old.tsv.

-- Scope lock: only documents/document_search rows whose doctype is Item.

DELETE FROM document_search WHERE tenant_id='demo' AND doctype='Item' AND name='RONNHUA_INOX';

DELETE FROM documents WHERE tenant_id='demo' AND doctype='Item' AND name='RONNHUA_INOX';

DELETE FROM document_search WHERE tenant_id='demo' AND doctype='Item' AND name='TP-BO3LADAY';

DELETE FROM documents WHERE tenant_id='demo' AND doctype='Item' AND name='TP-BO3LADAY';

DELETE FROM document_search WHERE tenant_id='demo' AND doctype='Item' AND name='BỘ BA LÁ ĐÁY + LÁ ĐẦU';

DELETE FROM documents WHERE tenant_id='demo' AND doctype='Item' AND name='BỘ BA LÁ ĐÁY + LÁ ĐẦU';

ON CONFLICT(tenant_id,doc_key) DO UPDATE SET
  payload_json=json_patch(documents.payload_json,excluded.payload_json),
  modified_at=excluded.modified_at,
  modified_by=excluded.modified_by,
  version=documents.version+1
WHERE documents.payload_json<>json_patch(documents.payload_json,excluded.payload_json);

